const aiItems = $input.all();
const jobItems = $('Sanitize AI Input').all();

const results = aiItems.map((item, index) => {
  let rawText = null;

  try {
    // Extract raw text from OpenAI / OpenRouter response
    rawText = item.json.output?.[0]?.content?.[0]?.text 
           || item.json.message?.content 
           || item.json.text 
           || (typeof item.json === 'string' ? item.json : null);

    if (!rawText) {
      throw new Error('Missing AI text output');
    }

    rawText = rawText
      .replace(/```json\n?/g, '')
      .replace(/```\n?/g, '')
      .trim();

    const parsed = JSON.parse(rawText);
    const jobData = jobItems[index]?.json || {};

    return {
      json: {
        ...jobData,
        verdict: parsed.verdict === true || parsed.verdict === 'true',
        signalStrength: parsed.signalStrength || '',
        functionalArea: parsed.functionalArea || '',
        whySignalMatters: parsed.whySignalMatters || '',
        rejectionReason: parsed.rejectionReason || '',
        error: false
      }
    };

  } catch (error) {
    const jobData = jobItems[index]?.json || {};
    return {
      json: {
        ...jobData,
        verdict: false,
        error: true,
        errorMessage: error.message,
        rawText,
        index
      }
    };
  }
});

return results;

function normComp(s) {
  if (!s) return '';
  let x = String(s).toLowerCase().trim().replace(/\s+/g, ' ');
  x = x.replace(/[.,/\\&'"`\-()]/g, ' ');
  x = x.replace(/\b(inc|incorporated|corp|corporation|llc|llp|ltd|limited|co|company|holdings|holding|group|the|gmbh|mbh|ug|ag|kg|ohg|se|ev|plc|bv|nv|sarl|sas|sa|srl|spa|oy|ab|as|aps|pte)\b/g, ' ');
  return x.replace(/\s+/g, ' ').trim();
}

function normDom(d) {
  if (!d) return '';
  let str = String(d).toLowerCase().trim().replace(/^https?:\/\//, '').replace(/^www\./, '');
  if (str.includes('linkedin.com/company/')) {
    const match = str.match(/linkedin\.com\/company\/([^/?#]+)/);
    return match ? `linkedin.com/company/${match[1]}` : '';
  }
  return str.split('/')[0].split('?')[0].trim();
}

function normLinkedin(url) {
  if (!url) return '';
  let str = String(url).toLowerCase().trim().replace(/^https?:\/\//, '').replace(/^www\./, '');
  if (str.includes('linkedin.com/company/')) {
    const match = str.match(/linkedin\.com\/company\/([^/?#]+)/);
    return match ? `linkedin.com/company/${match[1]}` : '';
  }
  return '';
}

return $input.all().map(item => {
  const j = item.json || {};
  const rawCompany = j.companyName || j.company || j.Company || j.company_name || j['Company Name'] || j.name || '';
  const rawCountry = j.country || j.location || j.Country || j.Location || '';
  const rawWebsite = j.companyWebsite || j.website || j.domain || j['Company Domain'] || j.company_domain || j.url || '';
  const rawLinkedin = j.companyLinkedinUrl || j.company_linkedin || j.linkedin || j['LinkedIn URL'] || j.linkedinUrl || '';

  const company = normComp(rawCompany);
  const country = rawCountry.toString().toLowerCase().trim();
  const domain = normDom(rawWebsite);
  const compLinkedin = normLinkedin(rawLinkedin);

  const dedupKey = company ? `${company}|${country || 'us'}` : '';
  const companyKey = company;

  return {
    json: {
      ...j,
      companyName: j.companyName || rawCompany,
      country: j.country || rawCountry,
      companyWebsite: j.companyWebsite || rawWebsite,
      companyLinkedinUrl: j.companyLinkedinUrl || rawLinkedin,
      _normCompany: company,
      _normDomain: domain,
      _normLinkedin: compLinkedin,
      dedupKey: j.dedupKey || dedupKey,
      companyKey: j.companyKey || companyKey
    }
  };
});

const safeAll = (nodeName) => {
  try {
    return $(nodeName).all();
  } catch (e) {
    return [];
  }
};

function normComp(s) {
  if (!s) return '';
  let x = String(s).toLowerCase().trim().replace(/\s+/g, ' ');
  x = x.replace(/[.,/\\&'"`\-()]/g, ' ');
  x = x.replace(/\b(inc|incorporated|corp|corporation|llc|llp|ltd|limited|co|company|holdings|holding|group|the|gmbh|mbh|ug|ag|kg|ohg|se|ev|plc|bv|nv|sarl|sas|sa|srl|spa|oy|ab|as|aps|pte)\b/g, ' ');
  return x.replace(/\s+/g, ' ').trim();
}

function normDom(d) {
  if (!d) return '';
  let str = String(d).toLowerCase().trim().replace(/^https?:\/\//, '').replace(/^www\./, '');
  if (str.includes('linkedin.com/company/')) {
    const match = str.match(/linkedin\.com\/company\/([^/?#]+)/);
    return match ? `linkedin.com/company/${match[1]}` : '';
  }
  return str.split('/')[0].split('?')[0].trim();
}

function normLinkedin(url) {
  if (!url) return '';
  let str = String(url).toLowerCase().trim().replace(/^https?:\/\//, '').replace(/^www\./, '');
  if (str.includes('linkedin.com/company/')) {
    const match = str.match(/linkedin\.com\/company\/([^/?#]+)/);
    return match ? `linkedin.com/company/${match[1]}` : '';
  }
  return '';
}

const scraped = $('Add Keys').all();
const jobsRows = safeAll('Get Jobs rows');
const rejRows = safeAll('Get Rejected rows');
const supRows = safeAll('Get Suppression rows');

const TTL = 90 * 24 * 60 * 60 * 1000;
const now = Date.now();

// 1. Existing Accepted Jobs / Signals
const existingDedupKeys = new Set();
const existingCompanies = new Set();
const existingDomains = new Set();
const existingLinkedin = new Set();

for (const r of jobsRows) {
  const j = r.json || {};
  const dk = (j.dedupKey || '').toString().trim();
  if (dk) existingDedupKeys.add(dk);

  const rawComp = j.companyName || j.company || j.Company || j['Company Name'] || '';
  const c = normComp(rawComp);
  if (c) existingCompanies.add(c);

  const dom = normDom(j.companyWebsite || j.domain || j['Company Domain'] || j.website || '');
  if (dom && dom !== 'linkedin.com') existingDomains.add(dom);

  const lk = normLinkedin(j.companyLinkedinUrl || j.linkedin || j['LinkedIn URL'] || '');
  if (lk) existingLinkedin.add(lk);
}

// 2. Rejected Companies (within 90-day TTL)
const rejectedDedupKeys = new Set();
const rejectedCompanies = new Set();

for (const r of rejRows) {
  const j = r.json || {};
  const dk = (j.dedupKey || '').toString().trim();
  const rawComp = j.companyName || j.company || j.Company || '';
  const c = normComp(rawComp);

  if (!dk && !c) continue;

  const ts = Date.parse(j.rejectedAt || '');
  if (isNaN(ts) || (now - ts) < TTL) {
    if (dk) rejectedDedupKeys.add(dk);
    if (c) rejectedCompanies.add(c);
  }
}

// 3. Suppression Contacts (Scott's Client / Relationship List)
const supCompanies = new Set();
const supDomains = new Set();
const supLinkedin = new Set();

for (const r of supRows) {
  const j = r.json || {};
  const dncRaw = String(j.doNotContact == null ? '' : j.doNotContact).trim().toLowerCase();
  const hasDncFlag = dncRaw === 'true' || dncRaw === 'yes' || dncRaw === '1';
  let hold = false;
  if (j.contactAfterDate) {
    const t = Date.parse(j.contactAfterDate);
    if (!isNaN(t) && t > now) hold = true;
  }

  const isSuppressed = (j.doNotContact === undefined && j.contactAfterDate === undefined) || hasDncFlag || hold;

  if (isSuppressed) {
    const rawComp = j.Company || j.company || j.companyName || j['Company Name'] || '';
    const c = normComp(rawComp);
    if (c) supCompanies.add(c);

    const rawDom = j['Company Domain'] || j.domain || j.companyWebsite || j.website || '';
    const dom = normDom(rawDom);
    if (dom && dom !== 'linkedin.com') supDomains.add(dom);

    const rawLk = j['LinkedIn URL'] || j.linkedin || j.companyLinkedinUrl || '';
    const lk = normLinkedin(rawLk);
    if (lk) supLinkedin.add(lk);
  }
}

// 4. Static Data for In-Run Loop Dedup
const _sd = $getWorkflowStaticData('global');
_sd.runStats = _sd.runStats || {
  scraped: 0,
  duplicates: 0,
  ruleFiltered: 0,
  aiPassed: 0,
  aiRejected: 0,
  amfSent: 0,
  aiParseErrors: 0,
  ruleReasons: {}
};
_sd.seenKeys = _sd.seenKeys || {};
_sd.seenCompanies = _sd.seenCompanies || {};
_sd.seenDomains = _sd.seenDomains || {};
_sd.seenLinkedin = _sd.seenLinkedin || {};

// 5. Filter Scraped Items
const kept = scraped.filter(it => {
  const j = it.json || {};
  const dk = (j.dedupKey || '').toString().trim();
  const c = j._normCompany || normComp(j.companyName || j.company || j.Company || '');
  const dom = j._normDomain || normDom(j.companyWebsite || j.domain || j.website || '');
  const lk = j._normLinkedin || normLinkedin(j.companyLinkedinUrl || j.linkedin || '');

  if (!c && !dom && !dk) return false;

  if (dk && existingDedupKeys.has(dk)) return false;
  if (dk && rejectedDedupKeys.has(dk)) return false;

  if (c && existingCompanies.has(c)) return false;
  if (c && rejectedCompanies.has(c)) return false;
  if (c && supCompanies.has(c)) return false;

  if (dom && dom !== 'linkedin.com') {
    if (existingDomains.has(dom)) return false;
    if (supDomains.has(dom)) return false;
  }

  if (lk) {
    if (existingLinkedin.has(lk)) return false;
    if (supLinkedin.has(lk)) return false;
  }

  return true;
});

// 6. In-Run Loop Deduplication
const fresh = kept.filter(it => {
  const j = it.json || {};
  const dk = (j.dedupKey || '').toString().trim();
  const c = j._normCompany || normComp(j.companyName || j.company || j.Company || '');
  const dom = j._normDomain || normDom(j.companyWebsite || j.domain || j.website || '');
  const lk = j._normLinkedin || normLinkedin(j.companyLinkedinUrl || j.linkedin || '');

  if (dk && _sd.seenKeys[dk]) return false;
  if (c && _sd.seenCompanies[c]) return false;
  if (dom && dom !== 'linkedin.com' && _sd.seenDomains[dom]) return false;
  if (lk && _sd.seenLinkedin[lk]) return false;

  return true;
});

for (const it of fresh) {
  const j = it.json || {};
  const dk = (j.dedupKey || '').toString().trim();
  const c = j._normCompany || normComp(j.companyName || j.company || j.Company || '');
  const dom = j._normDomain || normDom(j.companyWebsite || j.domain || j.website || '');
  const lk = j._normLinkedin || normLinkedin(j.companyLinkedinUrl || j.linkedin || '');

  if (dk) _sd.seenKeys[dk] = true;
  if (c) _sd.seenCompanies[c] = true;
  if (dom && dom !== 'linkedin.com') _sd.seenDomains[dom] = true;
  if (lk) _sd.seenLinkedin[lk] = true;
}

_sd.runStats.scraped += scraped.length;
_sd.runStats.duplicates += Math.max(0, scraped.length - fresh.length);

if (fresh.length === 0) {
  return [{ json: { _skip: true, companyName: '__skip__' } }];
}

return fresh;

const items = $input.all().map(i => i.json).filter(j => j && !j.error);
const byCompany = {};

for (const j of items) {
  // Use companyKey or normalized companyName so different cities merge together
  const k = j.companyKey || j.companyName?.toLowerCase().trim();
  if (!k) continue;
  (byCompany[k] = byCompany[k] || []).push(j);
}

const out = [];
for (const k of Object.keys(byCompany)) {
  const roles = byCompany[k];
  const yes = roles.filter(r => r.verdict === true || r.verdict === 'true');
  if (yes.length === 0) continue;

  // Pick the newest job posting for this company
  yes.sort((a, b) => {
    const ta = Number(a.postedAtTimestamp) || Date.parse(a.postedAt || '') || 0;
    const tb = Number(b.postedAtTimestamp) || Date.parse(b.postedAt || '') || 0;
    return tb - ta;
  });

  out.push({ json: yes[0] });
}

return out;

const items = $input.all().map(i => i.json);
const byKey = {};

for (const j of items) {
  const k = j.dedupKey || j.companyName;
  if (!k) continue;
  (byKey[k] = byKey[k] || []).push(j);
}

const out = [];
const nowIso = new Date().toISOString().replace('T', ' ').slice(0, 19);

for (const k of Object.keys(byKey)) {
  const roles = byKey[k];
  const anyYes = roles.some(r => r.verdict === true || r.verdict === 'true');

  // If at least one job was accepted for this company, do not mark company as rejected
  if (anyYes) continue;

  const r = roles[0];
  out.push({
    json: {
      ...r,
      dedupKey: k,
      companyName: r.companyName || null,
      country: r.country || null,
      reason: r.rejectionReason || 'ai_rejected',
      rejectedAt: nowIso
    }
  });
}

return out;

const rows=[];
const runId = $execution.id;
const nowIso = DateTime.now().setZone('America/New_York').toFormat('yyyy-MM-dd HH:mm:ss');
const _sd=$getWorkflowStaticData('global');
if(_sd.runStats && !_sd.runStats.ruleReasons) _sd.runStats.ruleReasons={};

// These lists must stay identical to the ones in the "Job OK?" IF node.
// When they drift, a job dies at the IF but is logged here as 'unknown'.
const RECRUITER_NAME = ['recruiting','recruitment','recruiter','staffing',
  'executive search','search group','search partners','search firm',
  'search associates','search consultants',
  'talent group','talent solutions','talent partners',
  'headhunting','headhunter','placement','placements',
  'workforce solutions','human capital',
  'biospace','ladders','jobgether'];
const RECRUITER_IND = ['recruiting','recruitment','staffing'];
const BAD_TITLE = ['interim','freelance','contractor','pharmacovigilance','drug safety','medical writer'];
const OUTSOURCER = ['cdmo','contract development and manufacturing','we serve','our clients','outsourcing partner'];

for (const it of $input.all()) {
  const j = it.json || {};
  if (j._skip || j.companyName === '__skip__') continue;
  const reasons = [];

  const web = (j.companyWebsite || '').toString();
  if (!web) reasons.push('no_website');
  if (web.includes('careers.linkedin.com')) reasons.push('careers_linkedin');
  if (!j.postedAt) reasons.push('no_postedAt');

  const name = (j.companyName || '').toString().toLowerCase();
  if (RECRUITER_NAME.some(kw => name.includes(kw))) reasons.push('recruiter_name');

  const ind = (j.industries ?? '').toString().toLowerCase();
  if (RECRUITER_IND.some(kw => ind.includes(kw))) reasons.push('recruiter_industry');

  const title = (j.title ?? '').toString().toLowerCase();
  if (BAD_TITLE.some(kw => title.includes(kw))) reasons.push('excluded_title');

  const country = (j.companyAddress && j.companyAddress.addressCountry) || '';
  if (country !== 'US') reasons.push(country ? 'country_not_US' : 'country_missing');

  const slogan = (j.companySlogan ?? '').toString().toLowerCase();
  if (OUTSOURCER.some(kw => slogan.includes(kw))) reasons.push('outsourcer_slogan');

  const emp = Number(j.companyEmployeesCount ?? 0);
  if (isNaN(emp)) reasons.push('headcount_not_numeric');
  else if (emp > 1500) reasons.push('too_big_gte_1500');

  if(_sd.runStats){ const primary=reasons[0]||'unknown'; _sd.runStats.ruleReasons[primary]=(_sd.runStats.ruleReasons[primary]||0)+1; }
  rows.push({ json: {
    timestamp: nowIso,
    runId: runId,
    dedupKey: j.dedupKey || '',
    companyName: j.companyName || '',
    country: j.country || '',
    companyWebsite: web,
    companyEmployeesCount: (j.companyEmployeesCount === undefined ? '' : j.companyEmployeesCount),
    reason: reasons.join(',') || 'unknown'
  }});
}
if(_sd.runStats) _sd.runStats.ruleFiltered += rows.length;
return rows;

const sd=$getWorkflowStaticData('global');
if(!sd.runStats) return [];
const s=sd.runStats;
const row={ runId:$execution.id, startedAt:sd.runStartedAt||'', finishedAt:DateTime.now().setZone('Europe/Berlin').toFormat('yyyy-MM-dd HH:mm:ss'),
  workflow:'WF1 SISS', scraped:s.scraped, ruleFiltered:s.ruleFiltered, duplicates:s.duplicates,
  aiRejected:s.aiRejected, aiPassed:s.aiPassed, amfSent:s.amfSent,
  callbacks:'', valid:'', invalid:'', found:'', sentSmartlead:'', notFound:'', pendingChecked:'', retried:'', expired:'' };
row._aiParseErrors = s.aiParseErrors||0;
row._toAI = (s.scraped||0)-(s.duplicates||0)-(s.ruleFiltered||0);   // job posts that reached the AI
row._companies = (s.aiPassed||0)+(s.aiRejected||0);                  // unique companies after dedup collapse
// human-readable rule-filter breakdown (primary reason per job post -> sums to ruleFiltered)
const rr=s.ruleReasons||{};
const lbl={no_website:'no_website',careers_linkedin:'careers_linkedin',no_postedAt:'no_date',too_big_gte_2000:'too_big≥2000',recruiter_name:'recruiter',recruiter_industry:'recruiter',unknown:'other'};
const agg={}; for(const k of Object.keys(rr)){ const L=lbl[k]||k; agg[L]=(agg[L]||0)+rr[k]; }
row._ruleBreakdown = Object.keys(agg).sort((a,b)=>agg[b]-agg[a]).map(k=>k+' '+agg[k]).join(' · ') || '—';
delete sd.runStats; delete sd.runStartedAt;
return [{json:row}];

