function cleanString(value) {
  if (value === undefined || value === null) return '';

  let text = String(value);

  // Remove broken UTF-16 surrogate characters
  text = text.replace(/[\uD800-\uDBFF](?![\uDC00-\uDFFF])/g, '');
  text = text.replace(/(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/g, '');

  // Force safe UTF-8 roundtrip
  text = Buffer.from(text, 'utf8').toString('utf8');

  return text;
}

function cleanValue(value) {
  if (Array.isArray(value)) return value.map(cleanValue);

  if (value && typeof value === 'object') {
    return Object.fromEntries(
      Object.entries(value).map(([key, val]) => [key, cleanValue(val)])
    );
  }

  return cleanString(value);
}

return $input.all().map(item => {
  const j = cleanValue(item.json);

  const aiPromptText = cleanString(`
jobKey: ${j.link}
jobLink: ${j.link}
jobTitle: ${j.title}
standardizedTitle: ${j.standardizedTitle || ''}
companyName: ${j.companyName}
companyWebsite: ${j.companyWebsite}
companyLinkedinUrl: ${j.companyLinkedinUrl}
companyEmployeesCount: ${j.companyEmployeesCount}
companySlogan: ${j.companySlogan || ''}
companyIndustries: ${JSON.stringify(j.industries || [])}
companyDescription: ${(j.companyDescription || '').substring(0, 1000)}

location: ${j.location}
country: ${j.country || ''}
seniorityLevel: ${j.seniorityLevel}
employmentType: ${j.employmentType}
jobFunction: ${j.jobFunction}
workplaceTypes: ${JSON.stringify(j.workplaceTypes || [])}

jobDescription: ${(j.descriptionText || '').substring(0, 3000)}
`);

  return {
    json: {
      ...j,
      aiPromptText,
    },
  };
});

const norm = (u) => (u || '').replace(/^=/, '').split('?')[0].replace(/\/+$/, '').toLowerCase();

// Same normaliser as Add Keys and Dedup New Companies, so a name those nodes
// already treat as one company is treated as one company here too.
function normComp(s) {
  if (!s) return '';
  let x = String(s).toLowerCase().trim().replace(/\s+/g, ' ');
  x = x.replace(/[.,/\\&'"`\-()]/g, ' ');
  x = x.replace(/\b(inc|incorporated|corp|corporation|llc|llp|ltd|limited|co|company|holdings|holding|group|the|gmbh|mbh|ug|ag|kg|ohg|se|ev|plc|bv|nv|sarl|sas|sa|srl|spa|oy|ab|as|aps|pte)\b/g, ' ');
  return x.replace(/\s+/g, ' ').trim();
}

const leadByUrl = {};
for (const lead of $('Edit Fields1').all()) {
  const key = norm(lead.json.companyLinkedinUrl);
  if (key) leadByUrl[key] = lead.json;
}

const byCompany = {};
for (const item of $input.all()) {
  const p = item.json;
  if (!p.linkedinUrl) continue;

  const q = (p._meta && p._meta.query) || {};
  const key = norm(q.currentCompanies && q.currentCompanies[0]);
  if (!key || !leadByUrl[key]) continue;

  // The scraper sometimes returns a profile whose current employer is not the
  // company we searched. Live case: a self-employed profile in India came back
  // under GondolaBio and was the only HR result. Those poison the shortlist.
  const pos = (p.currentPositions && p.currentPositions[0]) || {};
  const claimed = normComp(pos.companyName);
  const target = normComp(leadByUrl[key].companyName);
  if (claimed && target && !claimed.includes(target) && !target.includes(claimed)) continue;

  // The HR run is the only one carrying functionIds, so the echoed query tells
  // us which pool a profile came from. No tagging nodes needed.
  const pool = (q.functionIds && q.functionIds.length) ? 'hr' : 'functional';

  if (!byCompany[key]) byCompany[key] = [];
  byCompany[key].push({
    pool: pool,
    fullName: [p.firstName, p.lastName].filter(Boolean).join(' '),
    title: pos.title || '',
    linkedinUrl: p.linkedinUrl,
    location: (p.location && p.location.linkedinText) || '',
    summary: (p.summary || '').slice(0, 400),
  });
}

// Emit one row per lead, INCLUDING companies where the search returned
// nobody. A company with no candidates must still reach the dashboard
// flagged, rather than silently disappearing from the run.
return Object.keys(leadByUrl).map((key) => {
  const all = byCompany[key] || [];

  const seen = {};
  const deduped = [];
  for (const c of all) {
    const k = c.pool + '|' + c.linkedinUrl;
    if (seen[k]) continue;
    seen[k] = 1;
    deduped.push(c);
  }

  return {
    json: Object.assign({}, leadByUrl[key], {
      candidateCount: deduped.length,
      candidates: deduped.filter((c) => c.pool === 'functional'),
      hrCandidates: deduped.filter((c) => c.pool === 'hr'),
    }),
  };
});

const groups = $('Group by Company').all();

// Walk the whole item and return the first string that looks like our AI JSON.
// Shape-agnostic on purpose: avoids Array.isArray() failing on n8n proxies
// and avoids guessing where the OpenAI node nested the content block.
function findAiText(node, depth) {
  if (node == null || depth > 8) return '';
  if (typeof node === 'string') {
    return node.indexOf('personFullName') !== -1 ? node : '';
  }
  if (typeof node === 'object') {
    for (const key of Object.keys(node)) {
      let child;
      try { child = node[key]; } catch (e) { continue; }
      const found = findAiText(child, depth + 1);
      if (found) return found;
    }
  }
  return '';
}

// ---------------------------------------------------------------------------
// Deterministic priority scoring.
//
// Replaces the model's self-reported `confidence`, which was ungrounded. In
// execution 6471 SpyGlass and Servier both cited Rule 2 in whyPersonSelected
// and came back "low" and "high" respectively, because the Pick Decision Maker
// prompt only defines confidence for Rule 1 and for two failure cases. Every
// other row - the normal path - had no instruction at all, so the model
// guessed. Same story on signalStrength: Filter Job graded Servier "high" on
// "indicating a significant capability build" with nothing in the post behind
// it.
//
// Nothing below calls a model. Every input is arithmetic or a substring test
// against text already on the item, so this adds zero OpenAI cost. That is
// also why the prompts were left alone rather than asked to quote evidence.
// ---------------------------------------------------------------------------

function rank(title) {
  const t = String(title || '').toLowerCase();
  if (/\b(co[\s-]?founder|founder|chief executive|ceo)\b/.test(t)) return 8;
  if (/\bchief\b/.test(t)) return 7;
  if (/\b(svp|evp|senior vice president|executive vice president)\b/.test(t)) return 6;
  if (/\b(vp|vice president)\b/.test(t)) return 5;
  if (/\bhead of\b|\bexec(utive)?\.? director\b/.test(t)) return 4;
  // Associate Director must be tested before the bare Director rule, and
  // "Senior Medical Director" must not fall through to it either - the words
  // are not adjacent, so /senior director/ would miss it.
  if (/\bassoc(iate)?\.? director\b/.test(t)) return 1;
  if (/\b(senior|sr\.?)\b[^,]{0,25}\bdirector\b/.test(t)) return 3;
  if (/\bdirector\b/.test(t)) return 2;
  return 0;
}

const FN_KEYS = {
  'medical affairs': ['medical affairs', 'field medical', 'medical', 'msl'],
  'clinical operations': ['clinical operation', 'clinical ops', 'clinical'],
  'quality': ['quality', 'qa', 'gxp', 'gmp', 'gcp'],
  'regulatory affairs': ['regulatory'],
};

function ownsFunction(title, area) {
  const t = String(title || '').toLowerCase();
  const a = String(area || '').toLowerCase().trim();
  if (!t || !a) return false;
  const keys = FN_KEYS[a] || [a];
  for (const k of keys) { if (t.indexOf(k) !== -1) return true; }
  return false;
}

// jobDescription is truncated to 1500 chars upstream in Edit Fields1, so a
// milestone buried late in a long post will be missed. That direction of error
// is deliberate: it under-rates rather than over-rates.
const RE_MILESTONE = /\bphase\s*(2|3|ii|iii)\b|\bpivotal\b|\b(ind|bla|nda|maa)\b|\blaunch\b|\bcommercial(ization|ise|ize)\b|\bfirst[\s-]in[\s-]human\b/i;
const RE_BUILD = /\bbuild(ing)?\b|\bscal(e|ing|able)\b|\bestablish(ing)?\b|\bstand(ing)?\s+up\b|\bfrom\s+the\s+ground\s+up\b|\bgrow(ing)?\s+the\s+team\b/i;
const RE_REPORTS = /reports?\s+(?:directly\s+)?to\s+(?:the\s+)?([^.\n;]{3,70})/i;

function scoreLead(lead, ai) {
  const desc = String(lead.jobDescription || '');
  const opening = String(lead.jobOpeningTitle || '');
  const pickTitle = String(ai.personJobTitle || '');
  const area = lead.functionalArea || '';
  const pool = Array.isArray(lead.candidates) ? lead.candidates.length : 0;

  if (!ai.personFullName || !ai.personLinkedinUrl) {
    return {
      priority: 'Review',
      priorityReason: 'Review - no contact found, nothing for Scott to action.',
    };
  }

  const reasons = [];

  // --- signal half, read straight from the posting -------------------------
  let signal = 0;
  const milestone = RE_MILESTONE.exec(desc);
  if (milestone) {
    signal += 3;
    reasons.push('post names ' + milestone[0].trim());
  } else if (RE_BUILD.test(desc)) {
    signal += 2;
    reasons.push('post describes a team build');
  } else {
    reasons.push('no milestone or build named in post');
  }
  // A senior opening IS the signal: the company is building or replacing the
  // head of the function. Run 6478 scored Intellia Low on a VP of Quality
  // opening at 502 employees, which is close to the strongest signal Scott
  // gets, so VP and above now counts double.
  if (rank(opening) >= 5) {
    signal += 2;
    reasons.push('the opening is a VP level function head');
  } else if (rank(opening) >= 4) {
    signal += 1;
    reasons.push('the opening is itself a function-head role');
  }

  // --- contact half --------------------------------------------------------
  let contact = 0;
  const gap = rank(pickTitle) - rank(opening);
  const reportsTo = RE_REPORTS.exec(desc);
  const reportsHit = !!reportsTo
    && rank(reportsTo[1]) > 0
    && Math.abs(rank(reportsTo[1]) - rank(pickTitle)) <= 1
    && ownsFunction(pickTitle, area);

  if (reportsHit) {
    contact += 3;
    reasons.push('post names the reporting line and it matches this person');
  } else if (gap >= 2) {
    contact += 2;
    reasons.push('sits ' + gap + ' rungs above the opening');
  } else if (gap === 1) {
    contact += 1;
    reasons.push('sits 1 rung above the opening');
  } else {
    contact -= 2;
    reasons.push('does NOT outrank the opening');
  }

  // When nobody in the pool owns the function, the function is vacant, which
  // is exactly why the company is hiring. Not carrying the function word
  // cannot count against a pick that was chosen as the reporting line.
  const poolOwns = Array.isArray(lead.candidates)
    && lead.candidates.some((c) => ownsFunction(c.title, area));

  if (ownsFunction(pickTitle, area)) {
    contact += 2;
    reasons.push('owns ' + area);
  } else if (!poolOwns) {
    contact += 1;
    reasons.push('no one owns ' + area + ' yet, this is the reporting line');
  } else {
    reasons.push('title does not name ' + area);
  }

  // A pool of one means nothing was actually compared. The pick may still be
  // right, but the scraper filter decided it, not the judgement.
  if (pool <= 1) {
    contact -= 2;
    reasons.push('only ' + pool + ' candidate returned, nothing was compared');
  } else {
    reasons.push(pool + ' candidates compared');
  }

  let priority;
  if (signal >= 2 && contact >= 3) priority = 'High';
  else if (signal + contact >= 3) priority = 'Medium';
  else priority = 'Low';

  return { priority: priority, priorityReason: priority + ' - ' + reasons.join('; ') + '.' };
}

