const url = ($json.companyLinkedinUrl || '').split('?')[0];
const size = Number($json.companyEmployeesCount) || 0;

// No jobTitles filter. Tested live against the actor on Encoded Therapeutics
// and Agenus: filtering on the function word returned 0 both times, while the
// same call with no title filter returned 17 and 21. Neither company HAS a
// Quality leader, which is exactly why they are hiring one, so the filter was
// searching for the person the job post proves does not exist. A title filter
// can only remove people, never add any, and a real VP of Quality is already
// inside the VP+ pull because they are a VP.
// functionIds and searchQuery were tested too. functionIds 22 returned 0,
// searchQuery returned 5 people none of whom were in Quality. Both dead ends.

// 220 Director, 300 VP, 310 CXO, 320 Owner or Partner.
// Director is added only under 50 employees, where the top of the company is
// often a Director. At Agenus, VP+ was 21 profiles on a single page, but VP+
// plus Director was 44 across two pages, and maxItems does not paginate
// (takePages is required). Adding 220 to a mid size company would silently
// cut the pool at 25 and could drop the real owner.
const seniorityLevelIds = size < 50
  ? ['220', '300', '310', '320']
  : ['300', '310', '320'];

const payload = {
  companies: [url],
  profileScraperMode: 'Short ($4 per 1k)',
  companyBatchMode: 'all_at_once',
  maxItems: 25,
  seniorityLevelIds
};

const out = {};
for (const k of Object.keys($json)) { out[k] = $json[k]; }
out.apifyInput = payload;
return { json: out };

const upstream = $('Parse AI Output').all();

// Shape-agnostic walk: find the string carrying our JSON, wherever
// the OpenAI node nested it.
function findAiText(node, depth) {
  if (node == null || depth > 8) return '';
  if (typeof node === 'string') {
    return node.indexOf('icebreaker') !== -1 ? node : '';
  }
  if (typeof node === 'object') {
    for (const key of Object.keys(node)) {
      let child;
      try { child = node[key]; } catch (e) { continue; }
      const found = findAiText(child, depth + 1);
      if (found) return found;
    }
  }
  return '';
}

// Blank-safe read: never emit undefined/null into the sheet.
const S = (v) => (v === undefined || v === null) ? '' : v;

// Edit Fields1's $now.setZone().toFormat() yields "Invalid DateTime" on
// this n8n version, so stamp the timestamps here instead.
const nowStamp = new Date().toISOString().slice(0, 19).replace('T', ' ');
const fixDate = (v) => (!v || v === 'Invalid DateTime') ? nowStamp : v;

return $input.all().map((item, i) => {
  const idx = (item.pairedItem && typeof item.pairedItem.item === 'number')
    ? item.pairedItem.item
    : i;
  const lead = (upstream[idx] && upstream[idx].json) || {};
  const text = findAiText(item.json, 0);

  let ai;
  try {
    const cleaned = text.replace(/^```(?:json)?/, '').replace(/```$/, '').trim();
    ai = JSON.parse(cleaned);
  } catch (e) {
    ai = { icebreaker: '', needsReview: true };
  }

  let icebreaker = ai.icebreaker || '';

  // Deterministic backstop for the prompt fix in Write Icebreaker.
  // In execution 174 the model returned the Quality template with its
  // slots unfilled and it reached the sheet as [FIRST], [COMPANY], [ROLE].
  // A prompt rule cannot guarantee this, so blank any message that still
  // carries a placeholder and let needsReview flag the row.
  if (/\[(FIRST|COMPANY|ROLE|SIGNAL|AREA)\]/.test(icebreaker)) icebreaker = '';

  // Slot-collapse backstop. In execution 6471 Servier came out as "building
  // in Medical Affairs around medical affairs": the AREA slot was filled with
  // the functional area the template sentence already names. The bracket test
  // above cannot see this, because the slot IS filled, just uselessly.
  // Only the two connector phrases are checked so a legitimate repeat like
  // "hiring for a Director of Quality" under the Quality template survives.
  const fa = String(lead.functionalArea || '').toLowerCase().trim();
  if (fa && icebreaker) {
    const lc = icebreaker.toLowerCase();
    if (lc.indexOf('around ' + fa) !== -1 || lc.indexOf('particularly ' + fa) !== -1) {
      icebreaker = '';
    }
  }

  const needsReview = (ai.needsReview === true) || !icebreaker;

  // Emit every sheet column explicitly so auto-map never drops a field.
  // Auto-map matches on header NAME, not position, so key order here is
  // irrelevant. The sheet has two status columns, "LeadStatus " (trailing
  // space) and "LeadStatus". Both are written until one is retired, because
  // an unmatched key is dropped silently and the wrong guess leaves the
  // dashboard's column permanently blank.
  return { json: {
    id: S(lead.id),
    signalType: S(lead.signalType) || 'Job_Post',
    LeadStatus: S(lead.LeadStatus) || 'New',
    dedupKey: S(lead.dedupKey),
    companyKey: S(lead.companyKey),
    contactRound: lead.contactRound || 1,
    companyName: S(lead.companyName),
    country: S(lead.country),
    companyWebsite: S(lead.companyWebsite),
    companyLinkedinUrl: S(lead.companyLinkedinUrl),
    companyEmployeesCount: S(lead.companyEmployeesCount),
    companyDescription: S(lead.companyDescription),
    location: S(lead.location),
    jobOpeningTitle: S(lead.jobOpeningTitle),
    link: S(lead.link),
    postedAt: S(lead.postedAt),
    personFullName: S(lead.personFullName),
    personJobTitle: S(lead.personJobTitle),
    personLinkedinUrl: S(lead.personLinkedinUrl),
    fundingRound: '',
    fundingAmount: '',
    investors: '',
    email: S(lead.email),
    leadNotes: '',
    zerobounceStatus: '',
    emailStatus: S(lead.emailStatus) || 'pending',
    icebreaker: icebreaker,
    dmCategory: S(lead.dmCategory),
    attempts: lead.attempts || 1,
    lastAttemptAt: fixDate(lead.lastAttemptAt),
    addedToCampaign: S(lead.addedToCampaign) || 'false',
    createdAt: fixDate(lead.createdAt),
    leadStage: S(lead.leadStage),
    leadStageUpdatedAt: '',
    triedCategories: '',
    jobDescription: S(lead.jobDescription),
    functionalArea: S(lead.functionalArea),
    confidence: S(lead.confidence),
    'LeadStatus ': S(lead.LeadStatus) || 'New',
    needsReview: needsReview,
    alternativeBuyers: S(lead.alternativeBuyers),
    whySignalMatters: S(lead.whySignalMatters),
    whyPersonSelected: S(lead.whyPersonSelected),
    signalStrength: S(lead.signalStrength),
    priority: S(lead.priority),
    priorityReason: S(lead.priorityReason),
    candidateCount: S(lead.candidateCount),
  }};
});

